if(argc==2&&std::string(argv[1])=="--version"){print_version();return 0;}std::string model,pr;int rows=0,dim=0,threads=1,count=0;for(int i=1;i<argc;++i){std::string a(argv[i]);if(a=="--model"&&i+1<argc)model=argv[++i];else if(a=="--rows"&&i+1<argc)rows=std::atoi(argv[++i]);else if(a=="--input-dim"&&i+1<argc)dim=std::atoi(argv[++i]);else if(a=="--positions"&&i+1<argc)pr=argv[++i];else if(a=="--threads"&&i+1<argc)threads=std::atoi(argv[++i]);else if(a=="--target-count"&&i+1<argc)count=std::atoi(argv[++i]);else{std::cerr<<"unknown or incomplete argument\n";return 64;}}std::vector<int>pos;if(model.empty()||rows<1||dim<1||threads<1||count<1||count>v14::MAX_TARGETS||!v14::parse_positions(pr,rows,pos)){std::cerr<<"invalid native receiver task-score arguments\n";return 64;}std::size_t n=static_cast<std::size_t>(rows)*dim;std::vector<float>input(n);std::cin.read(reinterpret_cast<char*>(input.data()),static_cast<std::streamsize>(n*sizeof(float)));if(static_cast<std::size_t>(std::cin.gcount())!=n*sizeof(float))return 65;std::vector<uint8_t>raw(static_cast<std::size_t>(count)*4);std::cin.read(reinterpret_cast<char*>(raw.data()),static_cast<std::streamsize>(raw.size()));if(static_cast<std::size_t>(std::cin.gcount())!=raw.size()||std::cin.peek()!=std::char_traits<char>::eof())return 66;std::vector<int32_t>targets;targets.reserve(static_cast<std::size_t>(count));for(int i=0;i<count;++i){std::size_t p=static_cast<std::size_t>(i)*4;uint32_t u=uint32_t(raw[p])|(uint32_t(raw[p+1])<<8)|(uint32_t(raw[p+2])<<16)|(uint32_t(raw[p+3])<<24);if(u>uint32_t(std::numeric_limits<int32_t>::max()))return 67;targets.push_back(static_cast<int32_t>(u));}if(!v14::valid_input(rows,dim,input))return 68;return run_native(model,rows,dim,threads,pos,input,targets);
